 p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(b)
def req(v,m):
 if not v:raise ValueError(m)
def sha(p):
 h=hashlib.sha256()
 with p.open('rb') as f:
  for b in iter(lambda:f.read(1048576),b''):h.update(b)
 return h.hexdigest()
report={'status':'FAIL','artifact_id':12581914557,'started_utc':datetime.now(timezone.utc).isoformat(),'python':sys.version,'platform':sys.platform,'codespace':os.environ.get('CODESPACE_NAME'),'cpu_count':os.cpu_count(),'meminfo':Path('/proc/meminfo').read_text(),'disk_before':list(shutil.disk_usage(r)),'phases':{}}
t0=time.monotonic();peak={'logical':0,'allocated':0,'rss':0};errors=[];stop=threading.Event();a=r/'inventory.zip';stage=r/'stage';dest=stage/'data/pit_retention_preparation_v1'
def sample():
 paths=([a] if a.exists() else [])+([p for p in stage.rglob('*') if p.is_file()] if stage.exists() else [])
 st=[p.stat() for p in paths];peak['logical']=max(peak['logical'],sum(x.st_size for x in st));peak['allocated']=max(peak['allocated'],sum(x.st_blocks*512 for x in st));peak['rss']=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss*1024
