 t=time.monotonic();v=f();report['phases'][n]=time.monotonic()-t;sample();print(n,'PASS',flush=True);return v
threading.Thread(target=monitor,daemon=True).start()
try:
 registry=json.loads(get('docs/audits/pr75_24b424c_review_20261025/freeze-and-identities.json'));save(r/'freeze-registry.json',json.dumps(registry).encode())
 for x in registry['files']:save(s/x['path'],get(x['path']))
 def freeze():
  out={}
  for x in registry['files']:
   b=(s/x['path']).read_bytes();out[x['path']]=hashlib.sha256(b).hexdigest()
   if x['mode']=='LF_normalized':b=b.replace(b'\r\n',b'\n')
   req(hashlib.sha256(b).hexdigest()==x['expected'],'frozen drift '+x['path'])
  return out
 before=freeze();report['frozen_before']=before
 blobs={}
 for name,expected in {'oss_inventory_retention.py':'20f86b0263bb2c8f65a122fa7852e84069e0bb74','pit_retention_preparation.py':'6a5128c829c3568ddd9ea14d5f213469bb939c6e'}.items():
  b=get(name);save(s/name,b);blobs[name]=hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest();req(blobs[name]==expected,'code blob mismatch')
 report['code_blobs']=blobs;sys.path.insert(0,str(s))
 import oss_inventory_retention as m
 import pit_retention_preparation as pit
 meta=phase('metadata',lambda:m.github('/actions/artifacts/12581914557'))
 save(r/'artifact-metadata.json',json.dumps(meta).encode())
 req(meta['id']==12581914557 and not meta['expired'] and meta['size_in_bytes']==1410368543,'artifact identity')
 req(meta['digest']=='sha256:d6974f86bfffe7365e6d43f90e6b9cfea194c380acf493100c3959084c48a1d2','digest identity')
 phase('download_and_digest',lambda:m.download_artifact(meta,a))
 def blocked(*args,**kwargs):raise RuntimeError('network blocked during offline validation')
 socket.socket.connect=blocked;socket.socket.connect_ex=blocked;socket.create_connection=blocked
 report['capacity']=phase('capacity',lambda:m.artifact_capacity(a))
