 req(prior['part_count']==27 and prior['objects']==7672,'counts');req(prior['bundle_sha256']=='d67d384240449d462447e8dddfc99c6757b1f1d167f3953fe87e2ebd97593e9d','bundle binding')
 raw,parts=phase('references',lambda:m.validate_inventory_references(stage,prior));req(len(parts)==27,'parts')
 phase('inner_zip_limits',lambda:m.validate_staged_packages(dest))
 phase('frozen_verifier',lambda:pit.verify_inventory_bundle(stage,prior))
 report['verified_parts']=len(parts);report['verified_unique_objects']=len(json.loads(raw)['objects']);req(report['verified_unique_objects']==7672,'objects')
 report['part_sha256']={p['bundle_path']:sha(stage/p['bundle_path']) for p in parts}
