 stop.set();sample();report['resource_peak']=peak;report['monitor_errors']=errors;report['elapsed_seconds']=time.monotonic()-t0;report['finished_utc']=datetime.now(timezone.utc).isoformat();report['disk_after']=list(shutil.disk_usage(r));save(r/'result.json',json.dumps(report,indent=2).encode());print(json.dumps({k:report[k] for k in ('status','resource_peak','elapsed_seconds')}),flush=True)
raise SystemExit(0 if report['status']=='PASS' else 1)
